from html.parser import HTMLParser
import re

class Checker(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ("input","br","hr","img","meta","link","area","base","col","embed","source","track","wbr") and not self.get_starttag_text().rstrip().endswith("/>"):
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if not self.stack:
            self.errors.append(f"unexpected close </{tag}> at {self.getpos()}")
            return
        if self.stack[-1] != tag:
            self.errors.append(f"mismatch: expected </{self.stack[-1]}> got </{tag}> at {self.getpos()}")
        else:
            self.stack.pop()

for f in ["Portfolio.dc.html","Pianist.dc.html","Horror.dc.html","Privacy.dc.html"]:
    text = open(f, encoding="utf-8").read()
    c = Checker()
    c.feed(text)
    print(f, "leftover stack:", c.stack, "errors:", c.errors[:5])
    # check dangling style= or style-hover leftover accidentally referencing {{ but stripped
    dyn_broken = re.findall(r'class="[a-z0-9-]+"[^>]*\{\{', text)
    print("  suspicious class+{{ combos:", len(dyn_broken))
EOF

