import re
from html.parser import HTMLParser

html_files = ["index.html","Pianist.dc.html","Horror.dc.html","Privacy.dc.html","404.html"]
css = open("style.css", encoding="utf-8").read()
css_classes = set(re.findall(r'\.([a-zA-Z0-9_-]+)(?=[\s,.:{])', css))

used_classes = set()
for f in html_files:
    text = open(f, encoding="utf-8").read()
    for m in re.findall(r'class="([^"]*)"', text):
        for tok in m.split():
            used_classes.add(tok)

print("Classes used in HTML but missing from CSS:", sorted(used_classes - css_classes))
print("Classes defined in CSS but unused in HTML:", sorted(css_classes - used_classes))

# structural check
class Checker(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        raw = self.get_starttag_text()
        if tag not in ("input","br","hr","img","meta","link","area","base","col","embed","source","track","wbr") and not raw.rstrip().endswith("/>"):
            self.stack.append(tag)
    def handle_startendtag(self, tag, attrs):
        pass
    def handle_endtag(self, tag):
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        elif self.stack:
            self.errors.append((tag, self.stack[-1], self.getpos()))

for f in html_files:
    text = open(f, encoding="utf-8").read()
    c = Checker()
    c.feed(text)
    print(f, "unclosed:", c.stack, "err count:", len(c.errors))
EOF
